/* @lc app=leetcode id=2940 lang=kotlin */ class Solution { fun leftmostBuildingQueries(heights: IntArray, queries: Array<IntArray>): IntArray = IntArray(queries.size).also { ans -> queries.indices.groupBy { maxOf(queries[it][0], queries[it][1]) }.let { g -> ArrayList<Int>().let { st -> (heights.size - 1 downTo 0).forEach { i -> g[i].orEmpty().forEach { qi -> minOf(queries[qi][0], queries[qi][1]).let { a -> ans[qi] = if (a == i || heights[a] < heights[i]) i else generateSequence(-1 to st.size - 1) { (lo, hi) -> if (lo >= hi) null else ((lo + hi + 1) / 2).let { m -> if (heights[st[m]] > heights[a]) m to hi else lo to m - 1 } }.last().first.let { p -> if (p < 0) -1 else st[p] } } }.let { generateSequence { st.lastOrNull()?.takeIf { heights[it] <= heights[i] } }.forEach { _ -> st.removeAt(st.size - 1) }.let { st.add(i) } } } } } } }